import type { ProviderBStorage, Reservation, Service, ServiceResponse, Stock } from "./types";
import { error } from "./reservation";
import {
  decodeProviderBReservationRow,
  decodeProviderBStockRow,
  encodeCanonicalDecimal,
  encodeProviderBReservationRow,
  encodeProviderBStockRow,
  isId,
  isQuantity,
  isRecord,
  isRevision,
} from "./validation";

type Command =
  | { op: "getAvailability"; sku: string }
  | { op: "getReservation"; reservationId: string }
  | { op: "reserve"; reservationId: string; sku: string; quantity: number };

type ReadResult<T> =
  | { kind: "found"; value: T }
  | { kind: "missing" }
  | { kind: "unavailable" };

function parseCommand(raw: unknown): Command | undefined {
  if (!isRecord(raw)) return undefined;
  switch (raw.op) {
    case "getAvailability":
      return isId(raw.sku) ? { op: raw.op, sku: raw.sku } : undefined;
    case "getReservation":
      return isId(raw.reservationId)
        ? { op: raw.op, reservationId: raw.reservationId } : undefined;
    case "reserve":
      return isId(raw.reservationId) && isId(raw.sku) && isQuantity(raw.quantity)
        ? { op: raw.op, reservationId: raw.reservationId, sku: raw.sku, quantity: raw.quantity }
        : undefined;
    default:
      return undefined;
  }
}

function reservationResponse(status: 200 | 201, reservation: Reservation): ServiceResponse {
  return {
    status,
    body: {
      reservationId: reservation.reservationId,
      sku: reservation.sku,
      quantity: reservation.quantity,
    },
  };
}

function availabilityResponse(stock: Stock): ServiceResponse {
  return {
    status: 200,
    body: {
      sku: stock.sku,
      totalUnits: stock.totalUnits,
      reservedUnits: stock.reservedUnits,
      availableUnits: stock.totalUnits - stock.reservedUnits,
    },
  };
}

function missingOrUnavailable(envelope: unknown): "missing" | "unavailable" {
  if (!isRecord(envelope) || envelope.ok !== false || !isRecord(envelope.error)) return "unavailable";
  return envelope.error.reason === "NO_SUCH_KEY" ? "missing" : "unavailable";
}

async function readStock(storage: ProviderBStorage, sku: string): Promise<ReadResult<Stock & { revisionText: string }>> {
  const envelope = await storage.read({ collection: "inventory", key: sku });
  if (!isRecord(envelope) || typeof envelope.ok !== "boolean") return { kind: "unavailable" };
  if (!envelope.ok) {
    const outcome = missingOrUnavailable(envelope);
    return outcome === "missing" ? { kind: "missing" } : { kind: "unavailable" };
  }
  const stock = decodeProviderBStockRow(envelope.value);
  if (stock === undefined || stock.sku !== sku) return { kind: "unavailable" };
  return { kind: "found", value: stock };
}

async function readReservation(storage: ProviderBStorage, reservationId: string): Promise<ReadResult<Reservation>> {
  const envelope = await storage.read({ collection: "reservations", key: reservationId });
  if (!isRecord(envelope) || typeof envelope.ok !== "boolean") return { kind: "unavailable" };
  if (!envelope.ok) {
    const outcome = missingOrUnavailable(envelope);
    return outcome === "missing" ? { kind: "missing" } : { kind: "unavailable" };
  }
  const reservation = decodeProviderBReservationRow(envelope.value);
  if (reservation === undefined || reservation.reservationId !== reservationId) return { kind: "unavailable" };
  return { kind: "found", value: reservation };
}

export function createProviderBReservationService({ storage }: { storage: ProviderBStorage }): Service {
  return {
    async handle(raw): Promise<ServiceResponse> {
      const command = parseCommand(raw);
      if (command === undefined) return error(400, "invalid_command");
      try {
        if (command.op === "getAvailability") {
          const stockResult = await readStock(storage, command.sku);
          if (stockResult.kind === "missing") return error(404, "stock_not_found");
          if (stockResult.kind === "unavailable") return error(500, "storage_unavailable");
          return availabilityResponse(stockResult.value);
        }

        const existingResult = await readReservation(storage, command.reservationId);
        if (existingResult.kind === "unavailable") return error(500, "storage_unavailable");
        if (command.op === "getReservation") {
          return existingResult.kind === "found"
            ? reservationResponse(200, existingResult.value)
            : error(404, "reservation_not_found");
        }
        if (existingResult.kind === "found") {
          return existingResult.value.sku === command.sku && existingResult.value.quantity === command.quantity
            ? reservationResponse(200, existingResult.value)
            : error(409, "reservation_conflict");
        }

        const stockResult = await readStock(storage, command.sku);
        if (stockResult.kind === "missing") return error(404, "stock_not_found");
        if (stockResult.kind === "unavailable") return error(500, "storage_unavailable");
        const stock = stockResult.value;
        if (stock.totalUnits - stock.reservedUnits < command.quantity) {
          return error(409, "insufficient_stock");
        }
        const nextRevision = stock.revision + 1;
        if (!isRevision(nextRevision)) return error(500, "storage_unavailable");

        const reservation: Reservation = {
          reservationId: command.reservationId,
          sku: command.sku,
          quantity: command.quantity,
        };
        const nextStock: Stock = {
          sku: stock.sku,
          totalUnits: stock.totalUnits,
          reservedUnits: stock.reservedUnits + command.quantity,
          revision: nextRevision,
        };
        const reservationRow = encodeProviderBReservationRow(reservation);
        const outcome = await storage.commitBatch({
          expectedRevisionText: stock.revisionText,
          stockRow: encodeProviderBStockRow(nextStock),
          reservationRow,
          outboxRows: [{
            key: "reservation.created:" + reservation.reservationId,
            category: "reservation",
            name: "created",
            payload: {
              bookingKey: reservationRow.bookingKey,
              itemKey: reservationRow.itemKey,
              unitsText: encodeCanonicalDecimal(reservation.quantity),
            },
          }],
        });
        if (outcome === "revision_conflict") return error(409, "commit_conflict");
        if (outcome !== "applied") return error(500, "storage_unavailable");
        return reservationResponse(201, reservation);
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

